/**
 * Types for the statically-mined repo content served from public/*.json
 * (generated by `npm run mine` → scripts/mine-content.mjs).
 * All of this data is lazily fetched — never bundled.
 */

// ---------- public/repo-bank.json (DSA tracker import bank) ----------
export interface BankProblem {
  id: string;            // `bank-${slug}`
  title: string;
  slug: string;
  url: string;           // LeetCode or GitHub source URL
  difficulty: 'Easy' | 'Medium' | 'Hard' | 'Unknown';
  topics: string[];
  sourceRepo: string;
  sourceStars: number;
}

export interface BankRepoEntry {
  repo: string;
  count: number;
  stars: number;
}

export interface RepoBankFile {
  generatedAt: string;
  problemCount: number;
  repoCount: number;
  repos: BankRepoEntry[];
  problems: BankProblem[];
}

// ---------- public/sd-library.json (System Design deep-dives) ----------
export interface SdLibraryTopic {
  id: string;
  title: string;
  repo: string;
  stars: number;
  category: string;
  kind: 'HLD' | 'LLD';
  headings: string[];
  content: string;       // raw markdown excerpt (<= 6000 chars)
  url: string;
}

export interface SdLibraryFile {
  generatedAt: string;
  topicCount: number;
  repoCount: number;
  topics: SdLibraryTopic[];
}

// ---------- public/repo-flashcards.json (importable Q/A decks) ----------
export interface BankCard {
  id: string;
  front: string;
  back: string;
  sourceRepo: string;
}

export interface BankDeck {
  name: string;
  cardCount: number;
  repos: { repo: string; stars: number; count: number }[];
  cards: BankCard[];
}

export interface RepoFlashcardsFile {
  generatedAt: string;
  deckCount: number;
  totalCards: number;
  decks: BankDeck[];
}

// ---------- public/repo-roadmaps.json (study plans for cross-links) ----------
export interface RepoPlan {
  id: string;
  repo: string;
  name: string;
  category: string;
  stars: number;
  language: string;
  url: string;
  summary: string;
  sections: string[];
}

export interface RepoRoadmapsFile {
  generatedAt: string;
  planCount: number;
  plans: RepoPlan[];
}
